{
  "name": "hci_tx_queue_remove_and_send",
  "confidence": "medium",
  "docstring": "Under an IRQ nesting lock, removes or searches for a pending HCI transmit packet matching two 16-bit identifiers, updates the next packet's ke timer/event state when needed, and sends it via hci_tx_packet.",
  "subsystem": "bt",
  "var_renames": {
    "result": "match_value0",
    "a2": "match_value1",
    "v2": "irq_lock_count_ptr",
    "v3": "hci_tx_queue_ctrl",
    "v4": "hci_tx_packet",
    "v5": "irq_lock_count",
    "v7": "irq_was_disabled",
    "v8": "next_hci_tx_packet",
    "v9": "tx_queue_ke_event",
    "v10": "current_timer_tick"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "uint16_t packet match field compared against match_value0 (possibly HCI connection handle)"
    },
    {
      "offset": 6,
      "meaning": "uint16_t packet match field compared against match_value1 (possibly HCI parameter/type)"
    },
    {
      "offset": 8,
      "meaning": "uint32_t packet ke timer/event value used when rescheduling after removal"
    },
    {
      "offset": 20,
      "meaning": "HCI transmit queue front pointer/list head in control block"
    },
    {
      "offset": 32,
      "meaning": "ke event lock/state structure associated with the HCI transmit queue"
    }
  ]
}
